import os,json,stat,time,signal
from datetime import datetime,timezone
out={'captured_utc':datetime.now(timezone.utc).isoformat(),'kernel':os.uname().release,'scope':'names and metadata only; no IPC payload opened','roots':[]}
def timeout(*args):raise TimeoutError('metadata deadline')
signal.signal(signal.SIGALRM,timeout)
for base in ['/sys/kernel/debug/ipc_logging','/d/ipc_logging']:
 item={'path':base,'contexts':[]};out['roots'].append(item)
 try:
  signal.setitimer(signal.ITIMER_REAL,1)
  with os.scandir(base) as it:
   names=[e.name for e in it]
  if len(names)>1024:raise ValueError('name count bound')
  item['context_entry_count']=len(names)
  for name in ['cnss','cnss-long']:
   if name not in names:continue
   p=base+'/'+name
   with os.scandir(p) as it:children=[e.name for e in it]
   if len(children)>16:raise ValueError('child count bound')
   c={'name':name,'allowed_entries':[n for n in ['log','log_cont'] if n in children]};item['contexts'].append(c)
   if 'log' in children:
    s=os.stat(p+'/log')
    c['log_metadata']={'mode':oct(stat.S_IMODE(s.st_mode)),'regular':stat.S_ISREG(s.st_mode),'dev':s.st_dev,'inode':s.st_ino}
  item['status']='observed'
 except Exception as e:item['status']='unavailable';item['error_type']=type(e).__name__;item['errno']=getattr(e,'errno',None)
 finally:signal.setitimer(signal.ITIMER_REAL,0)
print(json.dumps(out))

import os,json,signal
from datetime import datetime,timezone
out={'captured_utc':datetime.now(timezone.utc).isoformat(),'scope':'filtered existing mount metadata and fixed directory names; no mount or IPC payload read','debugfs_mounts':[],'fixed_directories':[]}
def timeout(*args):raise TimeoutError('metadata deadline')
signal.signal(signal.SIGALRM,timeout);signal.setitimer(signal.ITIMER_REAL,1)
try:
 with open('/proc/self/mountinfo','rb') as f:b=f.read(262145)
 if len(b)>262144:raise ValueError('mount metadata cap')
 for l in b.decode().splitlines():
  a,sep,z=l.partition(' - ')
  if sep and z.split()[0]=='debugfs':
   fields=a.split();out['debugfs_mounts'].append({'root':fields[3],'mountpoint':fields[4]})
 for p in ['/sys/kernel/debug','/d']:
  d={'path':p};out['fixed_directories'].append(d)
  try:
   d['is_directory']=os.path.isdir(p);d['is_symlink']=os.path.islink(p)
   if d['is_directory']:
    with os.scandir(p) as it:names=[e.name for e in it]
    if len(names)>4096:raise ValueError('name count cap')
    d['entry_count']=len(names);d['ipc_logging_present']='ipc_logging' in names
  except Exception as e:d['error_type']=type(e).__name__;d['errno']=getattr(e,'errno',None)
 out['status']='complete'
except Exception as e:out['status']='incomplete';out['error_type']=type(e).__name__
finally:signal.setitimer(signal.ITIMER_REAL,0)
print(json.dumps(out))

import os,json,signal,zlib
from datetime import datetime,timezone
out={'captured_utc':datetime.now(timezone.utc).isoformat(),'scope':'filtered PID1 mount metadata and exact compiled config flags; no mounts or IPC payload reads','pid1_debugfs_mounts':[],'config':{}}
def timeout(*args):raise TimeoutError('metadata deadline')
signal.signal(signal.SIGALRM,timeout)
for name,path,cap in [('pid1_mountinfo','/proc/1/mountinfo',262144),('kernel_config','/proc/config.gz',1048576)]:
 try:
  signal.setitimer(signal.ITIMER_REAL,1)
  with open(path,'rb') as f:b=f.read(cap+1)
  if len(b)>cap:raise ValueError('metadata byte cap')
  if name=='pid1_mountinfo':
   for l in b.decode().splitlines():
    a,sep,z=l.partition(' - ')
    if sep and z.split()[0]=='debugfs':
     fields=a.split();out['pid1_debugfs_mounts'].append({'root':fields[3],'mountpoint':fields[4]})
  else:
   d=zlib.decompressobj(16+zlib.MAX_WBITS);t=d.decompress(b,2097153)
   if len(t)>2097152 or not d.eof or d.unconsumed_tail:raise ValueError('config expansion bound')
   lines=t.decode().splitlines()
   for key in ['CONFIG_DEBUG_FS','CONFIG_IPC_LOGGING']:
    vals=[l for l in lines if l.startswith(key+'=') or l=='# '+key+' is not set']
    out['config'][key]=vals
  out[name+'_status']='observed'
 except Exception as e:out[name+'_status']='unavailable';out[name+'_error_type']=type(e).__name__;out[name+'_errno']=getattr(e,'errno',None)
 finally:signal.setitimer(signal.ITIMER_REAL,0)
print(json.dumps(out))
